python3 - <<'PY'
import urllib.request, urllib.error
for url in ['http://rates-api.corp.internal/','http://rates-api.corp.internal/docs','http://rates-api.corp.internal/openapi.json','http://rates-api.corp.internal/health']:
    try:
        with urllib.request.urlopen(url, timeout=5) as r:
            print(url, r.status, r.read(500))
    except urllib.error.HTTPError as e:
        print(url, 'HTTPError', e.code, e.read(200))
    except Exception as e:
        print(url, type(e).__name__, e)
PY
